logger = logging.getLogger(__name__)


def _cutoff():
    return datetime.utcnow() - timedelta(days=180)


def _candidates(session):
    return session.query(Customer).filter(Customer.updated_at < _cutoff())


def _purge(session):
    rows = _candidates(session).all()
    for row in rows:
        session.delete(row)
    session.commit()
    return len(rows)


@shared_task
def purge_inactive_customers():
    session = SessionLocal()
    try:
        removed = _purge(session)
        logger.info('purged %s customer records', removed)
        return removed
    finally:
        session.close()

