import logging

logger = logging.getLogger(__name__)


class SessionTelemetry:
    def __init__(self, session_id: str, salt: str):
        self.session_id = session_id
        self._salt = salt
        self._tags = []

    def with_actor(self, email: str):
        digest = hashlib.sha256((self._salt + email).encode()).hexdigest()[:16]
        self._tags.append(f'actor:{digest}')
        return self

    def with_step(self, step: str):
        self._tags.append(f'step:{step}')
        return self

    def emit(self) -> None:
        logger.info('session=%s tags=%s', self.session_id, ','.join(self._tags))


def track(*, session_id: str, salt: str, email: str) -> None:
    SessionTelemetry(session_id, salt).with_actor(email).with_step('open').emit()

