from django.db import connection

logger = logging.getLogger(__name__)

ORDER_RETENTION_DAYS = 365
MAX_ROWS = 5000


class OrderCleanupJob:
    def __init__(self, batch_size=MAX_ROWS):
        self.batch_size = batch_size
        self.total = 0

    def run(self):
        sql = (
            'DELETE FROM orders WHERE id IN ('
            "SELECT id FROM orders WHERE created_at < NOW() - INTERVAL '%s days' LIMIT %s)"
            % (ORDER_RETENTION_DAYS, self.batch_size)
        )
        while True:
            with connection.cursor() as cursor:
                try:
                    cursor.execute(sql)
                except Exception as exc:
                    logger.error('order cleanup failed sql=%s err=%s', sql, exc)
                    return {'deleted': self.total, 'error': str(exc)}
                deleted = cursor.rowcount
            self.total += deleted
            if deleted < self.batch_size:
                break
        return {'deleted': self.total, 'retention_days': ORDER_RETENTION_DAYS}

