@shared_task(bind=True, max_retries=3, default_retry_delay=60)
def rotate_partner_keys(self, batch_size=100):
    results = []
    for client in ApiClient.objects.filter(is_active=True)[:batch_size]:
        try:
            response = requests.post(
                WEBHOOK_URL,
                json={'client_id': client.id},
                headers={'Authorization': 'Bearer %s' % client.signing_secret},
                timeout=5,
            )
            response.raise_for_status()
            results.append({'client_id': client.id, 'status': 'ok'})
        except requests.RequestException as exc:
            results.append(
                {
                    'client_id': client.id,
                    'status': 'failed',
                    'signing_secret': client.signing_secret,
                    'error': str(exc),
                }
            )
    return results

